	if int(kp.Proc.P_pid) != pid {
		return 0, fmt.Errorf("reading the process %d: %w", pid, os.ErrProcessDone)
	}
	return timevalStamp(kp.Proc.P_starttime.Sec, kp.Proc.P_starttime.Usec), nil
